class Logger {
  -Destination[] destinations
  +log(level,message)
}
class LogRecord {
  +timestamp
  +level
  +message
  +threadName
}
class Destination {
  -minLevel
  -Formatter formatter
  -Sink sink
  +write(record)
}
class Formatter {
  <<interface>>
  +format(record)
}
class Sink {
  <<interface>>
  +write(text)
}
Logger --> Destination : fans out
Destination --> Formatter : formats
Destination --> Sink : writes
Logger --> LogRecord : creates

