class FileSink implements Sink {
  private final Writer w;
  FileSink(String path) {
    w = openFile(path, APPEND);   // opened once
  }
  void write(String s) {
    w.append(s + "\n");           // reused handle
  }
}

class FileSink {
  int count = 0;
  void write(String s) {
    w.append(s + "\n");
    if (++count % FLUSH_EVERY == 0) w.flush();  // bounded flush
  }
}

class Destination {
  BlockingQueue<LogRecord> q = new ArrayBlockingQueue<>(1024);
  void write(LogRecord r) {
    if (r.level().compareTo(minLevel) < 0) return;
    q.put(r);              // caller just enqueues
  }
  void drain() {           // single worker thread
    LogRecord r = q.take();
    sink.write(formatter.format(r));
  }
}
